"kind": "propose",
"summary": "Adjust liveness/readiness probe timeouts to accommodate new version's startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Pod failed liveness probe immediately after startup due to insufficient probe timeout",
    "supporting": ["ev-container_logs_tail", "ev-target_events", "ev-rollout_history", "ev-pod_states"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_broken",
    "summary": "Rollout changed the image, and the new revision's pods fail while the previous revision's work",
    "supporting": ["ev-rollout_history", "ev-pod_states"],
    "contradicting": ["earlier_revision_healthy"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    },
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow the application time to start before probes fail",
  "rationale": "The pod was killed during startup (killed_during_startup=true) with liveness probe failures. The current timeoutSeconds=1 is too short for the new version's startup time. Increasing timeouts to 5s aligns with typical startup durations and prevents premature probe failures.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-target_events", "ev-rollout_history", "ev-pod_states"],
  "cited_predicates": ["killed_during_startup", "probe_kills", "probe_timeouts"]
}
}
